function allProducts() {
  return ALL;
}
function productUrl(p) {
  return `https://gcoman.com/products/${p.category}/${p.id}`;
}

// src/lib/mcp/tools/search-products.ts
var search_products_default = defineTool2({
  name: "search_products",
  title: "Search products",
  description: "Search the Global Chemicals LLC product catalog (200+ industrial chemicals, lubricants, and lab equipment supplied in Oman/GCC) by keyword and optional category. Returns up to `limit` matches with title, category, short description, and canonical URL.",
  inputSchema: {
    query: z.string().trim().min(1).describe("Free-text search string matched against product title, description, and CAS number."),
    category: z.string().trim().optional().describe("Optional category id (see list_categories) to narrow the search, e.g. 'water-treatment'."),
    limit: z.number().int().min(1).max(50).default(10).describe("Maximum number of results to return (1-50).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, category, limit }) => {
    const q = query.toLowerCase();
    const source = allProducts().filter((p) => category ? p.category === category : true);
    const matches = source.filter((p) => {
      const hay = [
        p.title,
        p.description ?? "",
        JSON.stringify(p.details ?? {})
      ].join(" ").toLowerCase();
      return hay.includes(q);
    }).slice(0, limit).map((p) => ({
      id: p.id,
      title: p.title,
      category: p.category,
      description: p.description ?? "",
      url: productUrl(p)
    }));
    return {
      content: [
        {
          type: "text",
          text: matches.length === 0 ? `No products matched "${query}"${category ? ` in ${category}` : ""}.` : JSON.stringify(matches, null, 2)
        }
      ],
      structuredContent: { count: matches.length, results: matches }
    };
  }
});

// src/lib/mcp/tools/get-product.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.23.0";
import { z as z2 } from "npm:zod@^3.25.76";
var get_product_default = defineTool3({
  name: "get_product",
  title: "Get product details",
  description: "Fetch the full details for a single product by its category slug and product slug (as used in the gcoman.com URL /products/<category>/<slug>). Returns title, description, CAS number, applications, and other structured product data.",
  inputSchema: {
    category: z2.string().trim().min(1).describe("Category slug, e.g. 'water-treatment'."),
    slug: z2.string().trim().min(1).describe("Product slug, e.g. 'caustic-soda-flakes'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ category, slug }) => {
    const product = allProducts().find((p) => p.category === category && p.id === slug);
    if (!product) {
      return {
        content: [{ type: "text", text: `No product found for ${category}/${slug}.` }],
        isError: true
      };
    }
    const enriched = { ...product, url: productUrl(product) };
    return {
      content: [{ type: "text", text: JSON.stringify(enriched, null, 2) }],
      structuredContent: { product: enriched }
    };
  }
});

// src/lib/mcp/tools/list-contact-submissions.ts
import { createClient } from "npm:@supabase/supabase-js@^2.76.1";
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.23.0";
import { z as z3 } from "npm:zod@^3.25.76";
function supabaseForUser(ctx) {
  return createClient(process.env.SUPABASE_URL, process.env.SUPABASE_PUBLISHABLE_KEY, {
    global: { headers: { Authorization: `Bearer ${ctx.getToken()}` } },
    auth: { persistSession: false, autoRefreshToken: false }
  });
}
var list_contact_submissions_default = defineTool4({
  name: "list_contact_submissions",
  title: "List recent contact submissions",
  description: "Admin only. Return the most recent contact-form submissions from gcoman.com (name, email, company, message, created_at). Requires the signed-in user to have the 'admin' role \u2014 non-admins receive an empty result under RLS.",
  inputSchema: {
    limit: z3.number().int().min(1).max(100).default(20).describe("Maximum submissions to return (1-100).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ limit }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    }
    const supabase = supabaseForUser(ctx);
    const { data, error } = await supabase.from("contact_submissions").select("id,name,email,company,phone,subject,message,created_at,status").order("created_at", { ascending: false }).limit(limit);
    if (error) {
      return { content: [{ type: "text", text: error.message }], isError: true };
    }
    const rows = data ?? [];
    return {
      content: [
        {
          type: "text",
          text: rows.length === 0 ? "No submissions visible to you (admin role required)." : JSON.stringify(rows, null, 2)
        }
      ],
      structuredContent: { count: rows.length, submissions: rows }
    };
  }
});

